def forca_da_senha(senha):
    if senha in ["123456", "senha", "admin"]:
        return "proibida"
    if len(senha) >= 12:
        return "forte"
    if len(senha) >= 8:
        return "ok"
    return "fraca"

print(forca_da_senha("gato"))   # fraca

desafio.solucao:
PROIBIDAS = ["123456", "admin", "senha", "qwerty"]
SIMBOLOS = "!@#$%&*?-_"

def auditar(senha):
    if senha.lower() in PROIBIDAS:
        return "proibida"

    maiuscula = any(c.isupper() for c in senha)
    numero    = any(c.isdigit() for c in senha)
    simbolo   = any(c in SIMBOLOS for c in senha)
    pontos = sum([maiuscula, numero, simbolo])

    if len(senha) >= 12 and pontos == 3:
        return "forte"
    if len(senha) >= 8 and pontos >= 2:
        return "ok"
    return "fraca"

for s in ["123456", "Gato#2026x", "admin", "senhalonga123"]:
    print(f"{s:15} -> {auditar(s)}")
